package com.votehub.controller;
import com.votehub.entity.*;import com.votehub.repository.*;import com.votehub.security.AuthService;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/user") @CrossOrigin(origins="http://localhost:5173") public class UserController {final AuthService auth;final VotingAuthorizationRepository ar;final ElectionRepository er;UserController(AuthService a,VotingAuthorizationRepository r,ElectionRepository e){auth=a;ar=r;er=e;}
@GetMapping("/history") public List<Map<String,Object>> history(@RequestHeader("Authorization")String h){User u=auth.user(h.replace("Bearer ",""));if(u.role!=User.Role.VOTER)throw new RuntimeException("Voter access required");return er.findAllByOrderByStartTimeDesc().stream().map(e->{var a=ar.findByElectionIdAndUserId(e.id,u.id).orElse(null);return Map.<String,Object>of("election",e.name,"status",a!=null&&a.used?"VOTED":"NOT VOTED","date",e.endTime.toString());}).toList();}}
